with with_prev as (select *, lag(event_time) over (partition by session_id order by event_time, id) as prev_event_time from web_events), gaps as (select *, case when prev_event_time is null or event_time > prev_event_time + interval 30 days then 1 else 0 end as is_new_session from with_prev), islands as (select *, sum(is_new_session) over (partition by session_id order by event_time, id rows between unbounded preceding and current row) as session_no from gaps) select s.id, s.session_id, s.page, s.is_new_session, s.session_no, (select sum(w2.duration_sec) from web_events w2 where w2.session_id = s.session_id) as sum_web_event_duration_sec from islands s
